# shellcheck shell=bash disable=SC2154  # variables come from apply-theme.sh and the earlier parts
# scripts/theme.d/09-dunst.sh: part of apply-theme.sh, sourced in order in the same shell (not run on its own)
# ==========================================
# 9. Dunst Notifications (dunstrc.d/99-color-engine.conf -> ~/.cache/theme/dunst.conf)
# ==========================================
cat <<EOF > "$CACHE_DIR/dunst.conf"
# Generated by apply-theme.sh (Dotfiles Color Engine)
[global]
    font = $FONT_UI 8
    frame_color = "$ACCENT"
    highlight = "$ACCENT"
    separator_color = frame

[urgency_low]
    background = "$BG"
    foreground = "$FG_MUTED"
    frame_color = "$BG_VISUAL"

[urgency_normal]
    background = "$BG"
    foreground = "$FG"
    frame_color = "$ACCENT"

[urgency_critical]
    background = "$BG"
    foreground = "$FG"
    frame_color = "$ANSI_RED"
    highlight = "$ANSI_RED"
EOF

mkdir -p "$HOME/.config/dunst/dunstrc.d"
ln -sf "$CACHE_DIR/dunst.conf" "$HOME/.config/dunst/dunstrc.d/99-color-engine.conf"

